// Normalize and dedupe.
// Input: one item from the HTTP node holding the raw CSV text in json.data.
// Output: one clean lead per item, duplicates and already-contacted removed.

function parseCsv(text) {
  const rows = [];
  const lines = text
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .split('\n')
    .filter(function (l) { return l.length > 0; });
  if (lines.length === 0) return rows;

  function parseLine(line) {
    const out = [];
    let cur = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const c = line[i];
      if (inQuotes) {
        if (c === '"' && line[i + 1] === '"') { cur += '"'; i++; }
        else if (c === '"') { inQuotes = false; }
        else { cur += c; }
      } else {
        if (c === '"') { inQuotes = true; }
        else if (c === ',') { out.push(cur); cur = ''; }
        else { cur += c; }
      }
    }
    out.push(cur);
    return out;
  }

  const headers = parseLine(lines[0]).map(function (h) { return h.trim().toLowerCase(); });
  for (let i = 1; i < lines.length; i++) {
    const cells = parseLine(lines[i]);
    const obj = {};
    headers.forEach(function (h, idx) { obj[h] = (cells[idx] || '').trim(); });
    rows.push(obj);
  }
  return rows;
}

// Pull the CSV text from the HTTP node output.
const first = $input.first();
const raw = (first && first.json && (first.json.data || first.json.body)) || '';
const leads = typeof raw === 'string' ? parseCsv(raw) : [];

// Build the set of emails we have already contacted, read from the log sheet.
const contacted = new Set();
try {
  const logRows = $('Read Contacted').all();
  for (const row of logRows) {
    const j = row.json || {};
    const e = (j.email || j.Email || j.lead_email || '').toString().trim().toLowerCase();
    if (e) contacted.add(e);
  }
} catch (err) {
  // Log sheet can be empty on the first run; that is expected.
}

const seen = new Set();
const out = [];
for (const lead of leads) {
  const email = (lead.email || '').toString().trim().toLowerCase();
  const normalized = {
    first_name: (lead.first_name || lead.firstname || '').trim(),
    last_name: (lead.last_name || lead.lastname || '').trim(),
    email: email,
    company: (lead.company || '').trim(),
    role: (lead.role || lead.title || '').trim(),
    website: (lead.website || lead.url || '').trim(),
    industry: (lead.industry || '').trim(),
  };

  // Drop fully empty rows.
  if (!normalized.first_name && !normalized.company && !email) continue;
  // Drop duplicates inside this run.
  if (email && seen.has(email)) continue;
  if (email) seen.add(email);
  // Drop anyone already in the log.
  if (email && contacted.has(email)) continue;

  out.push({ json: normalized });
}

return out;

// Assemble the draft.
// Runs once per lead. Input json is the Anthropic API response.
// The matching lead is fetched through the loop node's paired item.

const resp = $json || {};
const lead = $('Loop Over Leads').item.json;

let line = '';
if (resp && Array.isArray(resp.content) && resp.content.length > 0) {
  line = (resp.content[0].text || '').trim();
}
if (!line) {
  // Safe fallback so a bad API response never produces an empty draft.
  line = 'Saw what ' + (lead.company || 'your team') + ' is doing and wanted to reach out.';
}

const firstName = lead.first_name || 'there';
const subject = 'Quick idea for ' + (lead.company || 'your team');
const body = [
  line,
  '',
  'Hi ' + firstName + ', I help teams like ' + (lead.company || 'yours') +
    ' automate repetitive outbound and ops work. Worth a short call this week?',
  '',
  'Best,',
  'Colin',
].join('\n');

return {
  json: {
    contacted_at: new Date().toISOString(),
    first_name: lead.first_name || '',
    last_name: lead.last_name || '',
    email: lead.email || '',
    company: lead.company || '',
    role: lead.role || '',
    opening_line: line,
    subject: subject,
    draft_body: body,
    status: 'drafted',
  },
};
